/**
 * Traduction légère : le texte français sert de clé, l'anglais est dans EN.
 * Un texte absent du dictionnaire reste en français (jamais d'écran cassé).
 * La page web reçoit le même dictionnaire via /api/i18n.
 */
object I18n {
    @Volatile var english = false
        private set

    /** "auto" suit la langue de la tablette ; sinon "fr" ou "en". */
    fun apply(language: String) {
        english = when (language) {
            "en" -> true
            "fr" -> false
            else -> Locale.getDefault().language != "fr"
        }
    }

    val locale: Locale get() = if (english) Locale.ENGLISH else Locale.FRENCH

    fun t(fr: String): String = if (english) EN[fr] ?: fr else fr

